import { readFileSync } from 'node:fs'

class ConfigError extends Error {}
const fail = (m) => { throw new ConfigError(m) }

const newTable = () => ({ t: 'table', map: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

function parseLine(src, state) {
  let p = 0
  const peek = () => src[p]
  const skipWs = () => { while (p < src.length && isWs(src[p])) p++ }
  const atEnd = () => p >= src.length || src[p] === '#' || src[p] === ';'

  function parseBasic() {
    p++
    let out = ''
    for (;;) {
      if (p >= src.length) fail('unterminated string')
      const c = src[p]
      if (c === '"') { p++; return out }
      if (c === '\\') {
        const e = src[p + 1]
        if (e === undefined) fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) { out += map[e]; p += 2 }
        else if (e === 'u') {
          const h = src.slice(p + 2, p + 6)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16)); p += 6
        } else fail('invalid escape \\' + String.fromCodePoint(src.codePointAt(p + 1)))
      } else { out += c; p++ }
    }
  }
  function parseLiteral() {
    const e = src.indexOf("'", p + 1)
    if (e < 0) fail('unterminated string')
    const s = src.slice(p + 1, e); p = e + 1; return s
  }
  function parseName() {
    skipWs()
    const c = peek()
    if (c === '"') return parseBasic()
    if (c === "'") return parseLiteral()
    const s = p
    while (isBare(src[p])) p++
    if (p === s) fail('expected a name')
    return src.slice(s, p)
  }
  function parseDotted() {
    const parts = [parseName()]
    for (;;) {
      skipWs()
      if (peek() !== '.') return parts
      p++
      parts.push(parseName())
    }
  }

  // walk from table `tbl` (at path `base`) through `parts` minus the last; returns [table, path]
  function walk(tbl, base, parts, create = true) {
    let path = base.slice()
    for (const k of parts) {
      path = path.concat(k)
      let n = tbl.map.get(k)
      if (!n) { n = newTable(); tbl.map.set(k, n) }
      if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
      if (n.t !== 'table') fail(`${path.join('.')} is not a table`)
      tbl = n
    }
    return [tbl, path]
  }
  function assign(tbl, base, parts, value) {
    const [t, path] = walk(tbl, base, parts.slice(0, -1))
    const k = parts[parts.length - 1]
    if (t.map.has(k)) fail(`key ${path.concat(k).join('.')} is defined twice`)
    t.map.set(k, value)
  }

  function parseValue(base) {
    skipWs()
    if (atEnd() || ',]}'.includes(peek())) fail('expected a value')
    const c = peek()
    if (c === '"') return { t: 'string', v: parseBasic() }
    if (c === "'") return { t: 'string', v: parseLiteral() }
    if (c === '[') {
      p++
      const items = []
      for (;;) {
        skipWs()
        if (atEnd()) fail('unterminated array')
        if (peek() === ']') { p++; break }
        items.push(parseValue(base))
        skipWs()
        if (atEnd()) fail('unterminated array')
        if (peek() === ',') { p++; continue }
        if (peek() === ']') { p++; break }
        fail('unterminated array')
      }
      return { t: 'array', items, aot: false }
    }
    if (c === '{') {
      p++
      const tbl = newTable()
      skipWs()
      if (atEnd()) fail('unterminated inline table')
      if (peek() === '}') { p++; return tbl }
      for (;;) {
        skipWs()
        if (atEnd()) fail('unterminated inline table')
        const parts = parseDotted()
        skipWs()
        if (peek() !== '=') fail('expected = in an inline table')
        p++
        const v = parseValue(base)
        assign(tbl, base, parts, v)
        skipWs()
        if (atEnd()) fail('unterminated inline table')
        if (peek() === ',') { p++; continue }
        if (peek() === '}') { p++; break }
        fail('unterminated inline table')
      }
      return tbl
    }
    const s = p
    while (p < src.length && !isWs(src[p]) && !',]}'.includes(src[p])) p++
    const w = src.slice(s, p)
